    // --- UTILITIES ---
    
    function playSynthSound(name) {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);

        if (name === 'beep') {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(587.33, ctx.currentTime);
          gain.gain.setValueAtTime(0.08, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.12);
          osc.start();
          osc.stop(ctx.currentTime + 0.15);
        } else if (name === 'pop') {
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(146.83, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1174.66, ctx.currentTime + 0.1); 
          gain.gain.setValueAtTime(0.12, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);
          osc.start();
          osc.stop(ctx.currentTime + 0.12);
        } else if (name === 'chime') {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(880.00, ctx.currentTime);
          gain.gain.setValueAtTime(0.06, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
          osc.start();
          osc.stop(ctx.currentTime + 0.45);
        } else if (name === 'gameover') {
          osc.type = 'sawtooth';
          osc.frequency.setValueAtTime(220.00, ctx.currentTime);
          osc.frequency.linearRampToValueAtTime(110.00, ctx.currentTime + 0.6);
          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.6);
          osc.start();
          osc.stop(ctx.currentTime + 0.65);
        } else {
          osc.type = 'sine';
          osc.frequency.setValueAtTime(440.00, ctx.currentTime);
          gain.gain.setValueAtTime(0.05, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
          osc.start();
          osc.stop(ctx.currentTime + 0.22);
        }
      } catch (e) {
        console.warn("Synth audio ignored:", e);
      }
    }
  

    // --- TRANSCOMPILER PARSER ---
