    // --- STANDARD NATIVE ENGINE CORE ---
    class GreenfootEngine {
      constructor() {
        this.activeKeys = new Set();
        this.classesMap = {};
        this.speed = 65;
        this.worldInstance = null;
        this.actors = [];
        this.textLabels = [];
        this.gridSettings = GAME_GRID;
        this.worldBgUrl = null;
      }

      getSpeed() { return this.speed; }
      setSpeed(s) { this.speed = s; }
      
      isKeyDown(key) {
        const k = key.toLowerCase();
        if (k === 'left') return this.activeKeys.has('arrowleft');
        if (k === 'right') return this.activeKeys.has('arrowright');
        if (k === 'up') return this.activeKeys.has('arrowup');
        if (k === 'down') return this.activeKeys.has('arrowdown');
        if (k === 'space') return this.activeKeys.has(' ') || this.activeKeys.has('spacebar');
        return this.activeKeys.has(k);
      }

      clearKeys() { this.activeKeys.clear(); }

      matchesType(instanceState, ClassConstructor) {
        if (!ClassConstructor) return true;
        if (!instanceState) return false;

        // 1. Direct instanceof check
        try {
          if (instanceState instanceof ClassConstructor) return true;
        } catch (e) {
          // Ignore
        }

        // 2. Exact constructor check
        if (instanceState.constructor === ClassConstructor) return true;

        // 3. Match by class name (string or constructor.name)
        const typeStr = typeof ClassConstructor;
        if (typeStr === 'string') {
          const targetName = ClassConstructor.toLowerCase();
          const instName = (instanceState.className || instanceState.constructor?.name || '').toLowerCase();
          if (instName === targetName) return true;
        } else if (typeStr === 'function') {
          const targetName = (ClassConstructor.name || '').toLowerCase();
          const instName = (instanceState.className || instanceState.constructor?.name || '').toLowerCase();
          if (instName && targetName && instName === targetName) return true;
        }

        // 4. Manual prototype chain walking
        try {
          let proto = Object.getPrototypeOf(instanceState);
          while (proto) {
            if (proto.constructor === ClassConstructor) return true;
            if (typeStr === 'function' && ClassConstructor.name) {
              const pName = proto.constructor?.name;
              if (pName && pName.toLowerCase() === ClassConstructor.name.toLowerCase()) return true;
            }
            proto = Object.getPrototypeOf(proto);
          }
        } catch (e) {
          // Ignore
        }

        return false;
      }

      compile(classes, grid) {
        this.gridSettings = grid;
        this.classesMap = {};
        const self = this;

        const createSandbox = () => {
          class Color {
            constructor(r, g, b) {
              this.r = r; this.g = g; this.b = b;
            }
            toString() { return 'rgb(' + this.r + ',' + this.g + ',' + this.b + ')'; }
          }
          Color.RED = 'red'; Color.GREEN = 'green'; Color.BLUE = 'blue';
          Color.YELLOW = 'yellow'; Color.BLACK = 'black'; Color.WHITE = 'white'; Color.GRAY = 'gray';

          class GreenfootImage {
            constructor(arg1, arg2, arg3, arg4) {
              this.canvas = document.createElement('canvas');
              if (typeof arg1 === 'number' && typeof arg2 === 'number') {
                this.width = arg1; this.height = arg2;
                this.canvas.width = arg1; this.canvas.height = arg2;
                this.ctx = this.canvas.getContext('2d');
                this.clear();
              } else if (typeof arg1 === 'string' && arg2 === undefined) {
                this.width = 45; this.height = 45;
                this.canvas.width = 45; this.canvas.height = 45;
                this.ctx = this.canvas.getContext('2d');
                this.loadImage(arg1);
              } else if (typeof arg1 === 'string' && typeof arg2 === 'number') {
                this.width = Math.max(45, arg1.length * (arg2 * 0.6) + 12);
                this.height = arg2 + 12;
                this.canvas.width = this.width; this.canvas.height = this.height;
                this.ctx = this.canvas.getContext('2d');
                const textColor = arg3 ? arg3.toString() : '#ffffff';
                const bgColor = arg4 ? arg4.toString() : 'transparent';
                if (this.ctx) {
                  if (bgColor !== 'transparent') {
                    this.ctx.fillStyle = bgColor;
                    this.ctx.fillRect(0, 0, this.width, this.height);
                  }
                  this.ctx.fillStyle = textColor;
                  this.ctx.font = arg2 + 'px sans-serif';
                  this.ctx.textBaseline = 'middle';
                  this.ctx.fillText(arg1, 6, this.height / 2);
                }
              } else {
                this.width = 45; this.height = 45;
                this.canvas.width = 45; this.canvas.height = 45;
                this.ctx = this.canvas.getContext('2d');
              }
              this._sync();
            }

            loadImage(source) {
              if (!this.ctx) return;
              this.ctx.clearRect(0, 0, this.width, this.height);
              if (source.length <= 4 && source.match(/\\p{Emoji}/u)) {
                this.ctx.font = '32px sans-serif';
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText(source, this.width / 2, this.height / 2);
              } else {
                const presets = {
                  'wombat': '🐨', 'leaf': '🍃', 'rock': '🪨', 'crab': '🦀', 'lobster': '🦞', 'worm': '🐛',
                  'sand': '🏖️', 'brick': '🧱', 'block': '📦', 'gold': '🪙', 'balloon': '🎈', 'painter': '🐢'
                };
                const mapped = presets[source.toLowerCase()];
                if (mapped) {
                  this.ctx.font = '32px sans-serif';
                  this.ctx.textAlign = 'center';
                  this.ctx.textBaseline = 'middle';
                  this.ctx.fillText(mapped, this.width / 2, this.height / 2);
                } else if (source.startsWith('data:image') || source.startsWith('http') || source.includes('.')) {
                  const img = new Image();
                  img.crossOrigin = 'anonymous';
                  img.src = source;
                  img.onload = () => {
                    if (this.ctx) {
                      this.ctx.clearRect(0, 0, this.width, this.height);
                      this.ctx.drawImage(img, 0, 0, this.width, this.height);
                      this._sync();
                    }
                  };
                } else {
                  this.ctx.fillStyle = '#6b5840';
                  this.ctx.fillRect(2, 2, this.width - 4, this.height - 4);
                }
              }
              this._sync();
            }

            _sync() {
              try { this._dataUrl = this.canvas.toDataURL(); } catch(e){}
            }

            getWidth() { return this.width; }
            getHeight() { return this.height; }
            setColor(color) {
              const cStr = color ? color.toString() : '#000000';
              this.strokeColor = cStr; this.fillColor = cStr;
              if (this.ctx) { this.ctx.fillStyle = cStr; this.ctx.strokeStyle = cStr; }
            }
            clear() { if (this.ctx) this.ctx.clearRect(0, 0, this.width, this.height); this._sync(); }
            drawRect(x, y, w, h) { if (this.ctx) { this.ctx.strokeStyle = this.strokeColor; this.ctx.strokeRect(x, y, w, h); } this._sync(); }
            fillRect(x, y, w, h) { if (this.ctx) { this.ctx.fillStyle = this.fillColor; this.ctx.fillRect(x, y, w, h); } this._sync(); }
            drawOval(x, y, w, h) {
              if (this.ctx) {
                this.ctx.strokeStyle = this.strokeColor;
                this.ctx.beginPath(); this.ctx.ellipse(x + w / 2, y + h / 2, w / 2, h / 2, 0, 0, 2 * Math.PI); this.ctx.stroke();
              }
              this._sync();
            }
            fillOval(x, y, w, h) {
              if (this.ctx) {
                this.ctx.fillStyle = this.fillColor;
                this.ctx.beginPath(); this.ctx.ellipse(x + w / 2, y + h / 2, w / 2, h / 2, 0, 0, 2 * Math.PI); this.ctx.fill();
              }
              this._sync();
            }
            drawLine(x1, y1, x2, y2) { if (this.ctx) { this.ctx.strokeStyle = this.strokeColor; this.ctx.beginPath(); this.ctx.moveTo(x1, y1); this.ctx.lineTo(x2, y2); this.ctx.stroke(); } this._sync(); }
            drawString(text, x, y) { if (this.ctx) { this.ctx.fillStyle = this.fillColor; this.ctx.font = '12px sans-serif'; this.ctx.fillText(text, x, y); } this._sync(); }
            scale(w, h) {
              const tc = document.createElement('canvas'); tc.width = w; tc.height = h;
              const tx = tc.getContext('2d');
              if (tx) { tx.drawImage(this.canvas, 0, 0, w, h); this.canvas = tc; this.ctx = tx; this.width = w; this.height = h; }
              this._sync();
            }
            mirrorHorizontally() {
              if (this.ctx) {
                const tc = document.createElement('canvas'); tc.width = this.width; tc.height = this.height;
                const tx = tc.getContext('2d');
                if (tx) { tx.scale(-1, 1); tx.drawImage(this.canvas, -this.width, 0); this.ctx.clearRect(0,0,this.width,this.height); this.ctx.drawImage(tc,0,0); }
              }
              this._sync();
            }
            mirrorVertically() {
              if (this.ctx) {
                const tc = document.createElement('canvas'); tc.width = this.width; tc.height = this.height;
                const tx = tc.getContext('2d');
                if (tx) { tx.scale(1, -1); tx.drawImage(this.canvas, 0, -this.height); this.ctx.clearRect(0,0,this.width,this.height); this.ctx.drawImage(tc,0,0); }
              }
              this._sync();
            }
            drawImage(imgObj, x, y) {
              if (this.ctx && imgObj && imgObj.canvas) {
                this.ctx.drawImage(imgObj.canvas, x, y);
              }
              this._sync();
            }
          }

          class GreenfootSound {
            constructor(filename) { this.filename = filename; }
            play() { playSynthSound(this.filename); }
            stop() {}
            playLoop() {}
            isPlaying() { return false; }
            setVolume(v) {}
          }

          class World {
            constructor(width, height, cellSize) {
              this.width = width || grid.width;
              this.height = height || grid.height;
              this.cellSize = cellSize || grid.cellSize;
              this.bgImage = new GreenfootImage(this.width * this.cellSize, this.height * this.cellSize);
              this.bgImage.setColor(grid.backgroundColor || '#dfc293');
              this.bgImage.fillRect(0, 0, this.bgImage.width, this.bgImage.height);
              self.syncWorldBackground(this);
            }
            getWidth() { return this.width; }
            getHeight() { return this.height; }
            getCellSize() { return this.cellSize; }
            getBackground() { return this.bgImage; }
            setBackground(img) {
              if (typeof img === 'string') this.bgImage = new GreenfootImage(img);
              else this.bgImage = img;
              self.syncWorldBackground(this);
            }
            addObject(actorObj, x, y) { self.addObjectInstance(actorObj, x, y); }
            removeObject(actorObj) { self.removeObjectInstance(actorObj); }
            showText(text, x, y) { self.showTextPrompt(text, x, y); }
            getObjects(ClassConstructor) { return self.getObjectsOfClass(ClassConstructor); }
            isValidPosition(x, y) { return x >= 0 && x < this.width && y >= 0 && y < this.height; }
          }

          class Actor {
            constructor() {
              this.id = Math.random().toString(36).substring(2, 9);
              this.x = 0; this.y = 0; this.rotation = 0;
              this.className = this.constructor.name;
              const defaultEmoji = self.getEmojiForClass(this.className, classes);
              this.image = new GreenfootImage(defaultEmoji);
              self.updateActorImage(this);
            }
            act() {}
            getImage() {
              if (!this.image) {
                const defaultEmoji = self.getEmojiForClass(this.className, classes);
                this.image = new GreenfootImage(defaultEmoji);
              }
              return this.image;
            }
            setImage(img) {
              if (typeof img === 'string') this.image = new GreenfootImage(img);
              else this.image = img;
              self.updateActorImage(this);
            }
            getX() { return this.x; }
            getY() { return this.y; }
            getRotation() { return this.rotation; }
            setRotation(deg) { this.rotation = (deg % 360 + 360) % 360; self.updateActorData(this); }
            setLocation(nx, ny) { this.x = nx; this.y = ny; self.updateActorData(this); }
            move(dist) {
              const rad = (this.rotation * Math.PI) / 180;
              const dx = Math.round(dist * Math.cos(rad));
              const dy = Math.round(dist * Math.sin(rad));
              this.setLocation(this.x + dx, this.y + dy);
            }
            turn(deg) { this.setRotation(this.rotation + deg); }
            turnTowards(tx, ty) {
              const dx = tx - this.x; const dy = ty - this.y;
              const angle = Math.round((Math.atan2(dy, dx) * 180) / Math.PI);
              this.setRotation(angle);
            }
            isAtEdge() {
              const w = self.worldInstance; if (!w) return false;
              return this.x <= 20 || this.x >= w.getWidth() - 20 || this.y <= 20 || this.y >= w.getHeight() - 20;
            }
            getWorld() { return self.worldInstance; }
            getNewX(dist) {
              const rad = (this.rotation * Math.PI) / 180;
              return this.x + Math.round(dist * Math.cos(rad));
            }
            getNewY(dist) {
              const rad = (this.rotation * Math.PI) / 180;
              return this.y + Math.round(dist * Math.sin(rad));
            }
            getNeighbourInDirection() {
              const rad = (this.rotation * Math.PI) / 180;
              const dx = Math.round(25 * Math.cos(rad));
              const dy = Math.round(25 * Math.sin(rad));
              return { x: this.x + dx, y: this.y + dy };
            }
            isTouching(ClassConstructor) { return self.isTouchingType(this, ClassConstructor); }
            isTouchingAt(ClassConstructor, tx, ty) { return self.isTouchingTypeAt(this, ClassConstructor, tx, ty); }
            removeTouching(ClassConstructor) { self.removeTouchingType(this, ClassConstructor); }
            getOneIntersectingObject(ClassConstructor) {
              const actor = self.actors.find(a => {
                if (a.id === this.id) return false;
                const dist = Math.hypot(a.x - this.x, a.y - this.y);
                if (dist > 28) return false;
                return self.matchesType(a.instanceState, ClassConstructor);
              });
              return actor ? actor.instanceState : null;
            }
            getOneObjectAtOffset(dx, dy, ClassConstructor) {
              const tx = this.x + dx; const ty = this.y + dy;
              const actor = self.actors.find(a => {
                if (a.id === this.id) return false;
                const dist = Math.hypot(a.x - tx, a.y - ty);
                if (dist > 28) return false;
                return self.matchesType(a.instanceState, ClassConstructor);
              });
              return actor ? actor.instanceState : null;
            }
            getIntersectingObjects(ClassConstructor) {
              return self.actors
                .filter(a => {
                  if (a.id === this.id) return false;
                  const dist = Math.hypot(a.x - this.x, a.y - this.y);
                  if (dist > 28) return false;
                  return self.matchesType(a.instanceState, ClassConstructor);
                })
                .map(a => a.instanceState);
            }
            getNeighbours(distance, diagonal, ClassConstructor) {
              return self.actors
                .filter(a => {
                  if (a.id === this.id) return false;
                  const dist = Math.hypot(a.x - this.x, a.y - this.y);
                  if (dist > distance) return false;
                  return self.matchesType(a.instanceState, ClassConstructor);
                })
                .map(a => a.instanceState);
            }
            getObjectsAtOffset(dx, dy, ClassConstructor) {
              const tx = this.x + dx; const ty = this.y + dy;
              return self.actors
                .filter(a => {
                  if (a.id === this.id) return false;
                  const dist = Math.hypot(a.x - tx, a.y - ty);
                  if (dist > 28) return false;
                  return self.matchesType(a.instanceState, ClassConstructor);
                })
                .map(a => a.instanceState);
            }
            getObjectsInRange(radius, ClassConstructor) {
              return self.actors
                .filter(a => {
                  if (a.id === this.id) return false;
                  const dist = Math.hypot(a.x - this.x, a.y - this.y);
                  if (dist > radius) return false;
                  return self.matchesType(a.instanceState, ClassConstructor);
                })
                .map(a => a.instanceState);
            }
            playSound(soundName) { playSynthSound(soundName); }
          }

          const Greenfoot = {
            getRandomNumber(limit) { return Math.floor(Math.random() * limit); },
            isKeyDown(keyName) { return self.isKeyDown(keyName); },
            playSound(soundName) { playSynthSound(soundName); },
            setSpeed(speed) { self.setSpeed(speed); },
            getSpeed() { return self.getSpeed(); },
            getKey() { return null; }
          };

          return { Color, GreenfootImage, GreenfootSound, World, Actor, Greenfoot, Gfoot_Web: Greenfoot, Gfoot_WebImage: GreenfootImage, Gfoot_WebSound: GreenfootSound };
        };

        const compileSrc = transpileJavaToJs(classes);
        try {
          const compiledFn = new Function('context', compileSrc);
          const sandboxObj = createSandbox();
          const userConstructors = compiledFn(sandboxObj);

          this.classesMap['World'] = sandboxObj.World;
          this.classesMap['Actor'] = sandboxObj.Actor;
          this.classesMap['Greenfoot'] = sandboxObj.Greenfoot;
          this.classesMap['Color'] = sandboxObj.Color;
          this.classesMap['GreenfootImage'] = sandboxObj.GreenfootImage;
          this.classesMap['GreenfootSound'] = sandboxObj.GreenfootSound;
          this.classesMap['Gfoot_Web'] = sandboxObj.Gfoot_Web;
          this.classesMap['Gfoot_WebImage'] = sandboxObj.Gfoot_WebImage;
          this.classesMap['Gfoot_WebSound'] = sandboxObj.Gfoot_WebSound;

          classes.forEach(c => {
            if (userConstructors[c.name]) {
              this.classesMap[c.name] = userConstructors[c.name];
            }
          });
          return { ok: true, error: null };
        } catch (e) {
          console.error("Compile error", e);
          return { ok: false, error: e };
        }
      }

      syncWorldBackground(worldInst) {
        if (worldInst && worldInst.bgImage) {
          this.worldBgUrl = worldInst.bgImage._dataUrl;
        }
      }

      updateActorImage(actorObj) {
        if (actorObj && actorObj.image) {
          const matching = this.actors.find(a => a.id === actorObj.id);
          if (matching) {
            matching.instanceState = actorObj;
          }
        }
      }

      getEmojiForClass(className, classesList) {
        const found = classesList.find(c => c.name === className);
        return found ? found.icon : '❓';
      }

      createWorld(className) {
        const Cls = this.classesMap[className];
        if (!Cls) return false;
        try {
          this.worldInstance = new Cls(this.gridSettings.width, this.gridSettings.height, this.gridSettings.cellSize);
          return true;
        } catch(e) {
          console.error(e);
          return false;
        }
      }

      spawnActor(className, x, y, rotation = 0) {
        const Cls = this.classesMap[className];
        if (!Cls) return null;
        try {
          const actInstObj = new Cls();
          actInstObj.x = x;
          actInstObj.y = y;
          actInstObj.rotation = rotation;
          
          this.actors.push({
            id: actInstObj.id,
            className: className,
            x: x,
            y: y,
            rotation: rotation,
            variables: {},
            instanceState: actInstObj
          });
          return actInstObj;
        } catch(e) {
          console.error(e);
          return null;
        }
      }

      step() {
        const actorList = [...this.actors];
        actorList.forEach(a => {
          if (a.instanceState && typeof a.instanceState.act === 'function') {
            try { a.instanceState.act(); } catch(e){ console.error(e); }
          }
        });
      }

      getObjectsOfClass(ClassConstructor) {
        return this.actors
          .map(a => a.instanceState)
          .filter(inst => {
            return this.matchesType(inst, ClassConstructor);
          });
      }

      isTouchingType(sourceActor, ClassConstructor) {
        return this.actors.some(a => {
          if (a.id === sourceActor.id) return false;
          const dist = Math.hypot(a.x - sourceActor.x, a.y - sourceActor.y);
          if (dist > 28) return false;
          return this.matchesType(a.instanceState, ClassConstructor);
        });
      }

      isTouchingTypeAt(sourceActor, ClassConstructor, tx, ty) {
        return this.actors.some(a => {
          if (a.id === sourceActor.id) return false;
          const dist = Math.hypot(a.x - tx, a.y - ty);
          if (dist > 28) return false;
          return this.matchesType(a.instanceState, ClassConstructor);
        });
      }

      removeTouchingType(sourceActor, ClassConstructor) {
        const index = this.actors.findIndex(a => {
          if (a.id === sourceActor.id) return false;
          const dist = Math.hypot(a.x - sourceActor.x, a.y - sourceActor.y);
          if (dist > 28) return false;
          return this.matchesType(a.instanceState, ClassConstructor);
        });
        if (index !== -1) {
          this.actors.splice(index, 1);
        }
      }

      updateActorData(actorObj) {
        const matching = this.actors.find(a => a.id === actorObj.id);
        if (matching) {
          matching.x = actorObj.x;
          matching.y = actorObj.y;
          matching.rotation = actorObj.rotation;
        }
      }

      addObjectInstance(actorObj, x, y) {
        actorObj.x = x;
        actorObj.y = y;
        this.actors.push({
          id: actorObj.id,
          className: actorObj.className,
          x: x,
          y: y,
          rotation: actorObj.rotation || 0,
          variables: {},
          instanceState: actorObj
        });
      }

      removeObjectInstance(actorObj) {
        const index = this.actors.findIndex(a => a.id === actorObj.id);
        if (index !== -1) {
          this.actors.splice(index, 1);
        }
      }

      showTextPrompt(text, x, y) {
        const promptId = Math.random().toString(36).substring(3, 9);
        this.textLabels.push({ id: promptId, text, x, y });
        setTimeout(() => {
          this.textLabels = this.textLabels.filter(t => t.id !== promptId);
          renderSimulationState();
        }, 1500);
      }
    }

    // --- GAME INITIALIZATION BOOTSTRAP ---
    let engine = null;
    let isRunning = false;
    let speed = 65;
    let stepTimeout = null;
    let isMuted = false;

    const bgCanvas = document.getElementById('bgCanvas');
    const bgCtx = bgCanvas.getContext('2d');
    const gridCanvas = document.getElementById('gridCanvas');
    const gridCtx = gridCanvas.getContext('2d');
    const actorsLayer = document.getElementById('actorsLayer');
    const textLayer = document.getElementById('textLayer');

    // Mute/Sounds controller
    document.getElementById('btnMute').addEventListener('click', () => {
      isMuted = !isMuted;
      document.getElementById('btnMute').innerHTML = isMuted ? '<span>🔇</span> Sounds Off' : '<span>🔊</span> Sounds On';
    });

    function scaleViewport() {
      const w = engine && engine.worldInstance ? engine.worldInstance.getWidth() : GAME_GRID.width;
      const h = engine && engine.worldInstance ? engine.worldInstance.getHeight() : GAME_GRID.height;
      const cs = engine && engine.worldInstance ? engine.worldInstance.getCellSize() : GAME_GRID.cellSize;
      
      const widthPx = w * cs;
      const heightPx = h * cs;

      // Fit inside viewport width and height with neat margins
      const maxAvailableWidth = window.innerWidth - 48;
      // Leave space for the floating control dock and padding below/above
      const maxAvailableHeight = window.innerHeight - 150;

      let scale = 1;
      if (widthPx > 0 && heightPx > 0) {
        scale = Math.min(maxAvailableWidth / widthPx, maxAvailableHeight / heightPx);
        // Cap the max scale to 3.0, and min scale to 0.1
        scale = Math.min(3.0, Math.max(0.1, scale));
      }

      const worldCasing = document.getElementById('worldCasing');
      if (worldCasing) {
        worldCasing.style.transform = 'scale(' + scale + ')';
        worldCasing.style.transformOrigin = 'center center';
      }

      const scaledWrapper = document.getElementById('scaledWrapper');
      if (scaledWrapper) {
        scaledWrapper.style.width = (widthPx * scale) + 'px';
        scaledWrapper.style.height = (heightPx * scale) + 'px';
      }
    }

    // Attach resize listener
    window.addEventListener('resize', scaleViewport);

    function initGame() {
      engine = new GreenfootEngine();
      engine.setSpeed(speed);
      
      const compileReport = engine.compile(GAME_CLASSES, GAME_GRID);
      if (compileReport.ok) {
        // Build World
        const customWorldCls = GAME_CLASSES.find(c => c.superClass === 'World');
        const worldName = customWorldCls ? customWorldCls.name : 'World';
        engine.createWorld(worldName);

        // Spawn actors
        INITIAL_ACTORS.forEach(item => {
          engine.spawnActor(item.className, item.x, item.y, item.rotation);
        });

        renderWorldBackground();
        renderSimulationState();
        scaleViewport();
        
        // Auto-Play standalone loop immediately on startup as requested
        startLoop();
      } else {
        console.error("Standalone compile failed entirely!", compileReport.error);
      }
    }

    function renderWorldBackground() {
      const w = engine.worldInstance ? engine.worldInstance.getWidth() : GAME_GRID.width;
      const h = engine.worldInstance ? engine.worldInstance.getHeight() : GAME_GRID.height;
      const cs = engine.worldInstance ? engine.worldInstance.getCellSize() : GAME_GRID.cellSize;
      
      const widthPx = w * cs;
      const heightPx = h * cs;
      
      // Update canvas dimensions dynamically
      if (bgCanvas.width !== widthPx || bgCanvas.height !== heightPx) {
        bgCanvas.width = widthPx;
        bgCanvas.height = heightPx;
        
        const cont = document.getElementById('worldContainer');
        if (cont) {
          cont.style.width = widthPx + 'px';
          cont.style.height = heightPx + 'px';
        }
      }
      
      if (gridCanvas.width !== widthPx || gridCanvas.height !== heightPx) {
        gridCanvas.width = widthPx;
        gridCanvas.height = heightPx;
      }
      
      // Clear and draw background
      bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
      if (engine.worldBgUrl) {
        const bgImg = new Image();
        bgImg.src = engine.worldBgUrl;
        bgImg.onload = () => {
          bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
          bgCtx.drawImage(bgImg, 0, 0);
        };
      } else {
        bgCtx.fillStyle = GAME_GRID.backgroundColor || '#dfc293';
        bgCtx.fillRect(0, 0, bgCanvas.width, bgCanvas.height);
      }

      // Draw Grid Lattice lines
      gridCtx.clearRect(0,0,gridCanvas.width,gridCanvas.height);
      gridCtx.strokeStyle = 'rgba(0,0,0,0.06)';
      gridCtx.lineWidth = 1;

      // Draw horizontal
      for (let y = 0; y <= h; y++) {
        gridCtx.beginPath();
        gridCtx.moveTo(0, y * cs);
        gridCtx.lineTo(widthPx, y * cs);
        gridCtx.stroke();
      }
      // Draw vertical
      for (let x = 0; x <= w; x++) {
        gridCtx.beginPath();
        gridCtx.moveTo(x * cs, 0);
        gridCtx.lineTo(x * cs, heightPx);
        gridCtx.stroke();
      }
    }

    function renderSimulationState() {
      const w = engine.worldInstance ? engine.worldInstance.getWidth() : GAME_GRID.width;
      const h = engine.worldInstance ? engine.worldInstance.getHeight() : GAME_GRID.height;
      const cs = engine.worldInstance ? engine.worldInstance.getCellSize() : GAME_GRID.cellSize;

      // Render active actor elements
      actorsLayer.innerHTML = '';
      engine.actors.forEach(act => {
        const screenX = (act.x * cs) + (cs / 2);
        const screenY = (act.y * cs) + (cs / 2);

        const actWidth = (act.instanceState && act.instanceState.image) ? act.instanceState.image.width : cs;
        const actHeight = (act.instanceState && act.instanceState.image) ? act.instanceState.image.height : cs;

        const wrapper = document.createElement('div');
        wrapper.className = 'absolute select-none pointer-events-none transition-all duration-300 ease-out';
        wrapper.style.left = screenX + 'px';
        wrapper.style.top = screenY + 'px';
        wrapper.style.transform = 'translate(-50%, -50%) rotate(' + (act.rotation || 0) + 'deg)';
        wrapper.style.width = actWidth + 'px';
        wrapper.style.height = actHeight + 'px';

        const content = document.createElement('div');
        content.className = 'w-full h-full flex items-center justify-center select-none';

        if (act.instanceState && act.instanceState.image && act.instanceState.image._dataUrl) {
          const img = document.createElement('img');
          img.src = act.instanceState.image._dataUrl;
          img.className = 'w-[85%] h-[85%] object-contain pixelated';
          content.appendChild(img);
        } else {
          const emojiChar = EMOJI_MAP[act.className] || '🦊';
          content.innerText = emojiChar;
          content.style.fontSize = (Math.min(actWidth, actHeight) * 0.72) + 'px';
        }

        wrapper.appendChild(content);
        actorsLayer.appendChild(wrapper);
      });

      // Render Text prompts
      textLayer.innerHTML = '';
      engine.textLabels.forEach(label => {
        const screenX = (label.x * cs) + (cs / 2);
        const screenY = (label.y * cs) + (cs / 2);

        const lblDiv = document.createElement('div');
        lblDiv.className = 'absolute bg-black/85 text-white border border-[#333] px-1.5 py-0.5 rounded text-[10px] font-bold font-sans tracking-wide shadow-md transform -translate-x-1/2 -translate-y-1/2';
        lblDiv.style.left = screenX + 'px';
        lblDiv.style.top = screenY + 'px';
        lblDiv.innerText = label.text;
        
        textLayer.appendChild(lblDiv);
      });
    }

    // Key event listeners
    window.addEventListener('keydown', (e) => {
      if (engine) {
        engine.activeKeys.add(e.key.toLowerCase());
      }
      if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(e.key.toLowerCase())) {
        e.preventDefault();
      }
    });

    window.addEventListener('keyup', (e) => {
      if (engine) {
        engine.activeKeys.delete(e.key.toLowerCase());
      }
    });

    // Reset listener
    document.getElementById('btnReset').addEventListener('click', () => {
      stopLoop();
      initGame();
      if (!isMuted) playSynthSound('pop');
    });

    function startLoop() {
      if (stepTimeout) clearTimeout(stepTimeout);
      isRunning = true;
      if (!isMuted) playSynthSound('beep');
      scheduleNextStep();
    }

    function stopLoop() {
      isRunning = false;
      if (stepTimeout) {
        clearTimeout(stepTimeout);
        stepTimeout = null;
      }
      if (engine) engine.clearKeys();
    }

    function scheduleNextStep() {
      if (!isRunning) return;
      const currentSpeed = engine ? engine.getSpeed() : speed;
      const intervalRate = Math.max(5, 800 - (currentSpeed * 7.7));
      stepTimeout = setTimeout(executeStep, intervalRate);
    }

    function executeStep() {
      if (!engine) return;
      engine.step();
      renderSimulationState();
      if (isRunning) {
        scheduleNextStep();
      }
    }

    // Auto load
    initGame();
